    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>

    <div class="task-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move" @onclick="() => OnMove.InvokeAsync((Task.Id, MoveLeftStatus!))">← Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move" @onclick="() => OnMove.InvokeAsync((Task.Id, MoveRightStatus!))">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter, EditorRequired]
    public string ColumnStatus { get; set; } = default!;

    [Parameter]
    public EventCallback<(int TaskId, string NewStatus)> OnMove { get; set; }

    private static readonly string[] ColumnOrder = ["To Do", "In Progress", "Done"];

    private int ColumnIndex => Array.IndexOf(ColumnOrder, ColumnStatus);
    private bool ShowMoveLeft => ColumnIndex > 0;
    private bool ShowMoveRight => ColumnIndex < ColumnOrder.Length - 1;
    private string? MoveLeftStatus => ShowMoveLeft ? ColumnOrder[ColumnIndex - 1] : null;
    private string? MoveRightStatus => ShowMoveRight ? ColumnOrder[ColumnIndex + 1] : null;
}
"}

